1	// The coded production-validation grammar and judgment (#1530) — pure, no I/O.
2	// A verification issue states declarative PROBES on its first lines, each one
3	// URL and one assertion, in two classes with distinct failure meanings:
4	//
5	//   Live-probe:   <url> :: <assertion>   — the liveness gate. Any failing means
6	//                                          the release has not landed: the run
7	//                                          re-arms and comes back, and nothing
8	//                                          is judged.
9	//   Verify-probe: <url> :: <assertion>   — the verification itself, judged only
10	//                                          once every liveness probe passes. Any
11	//                                          failing is a real fault in production.
12	//
13	// Both classes are REQUIRED: without a liveness gate a verify failure cannot be
14	// told from a release that simply has not happened, and would reopen the
15	// original issue over nothing.
16	//
17	// Assertions, after the `::`:
18	//   status <n>                       the response code itself (the one op a
19	//                                    non-2xx response can pass)
20	//   [not ]contains <text>            body carries the literal text
21	//   [not ]matches /<re>/[flags]      body matches the JS regex
22	//   json <path> exists               dotted path resolves to a value
23	//   json <path> == <value>           strict-deep equality with the JSON value
24	//   json <path> != <value>           its negation
25	//   json <path> >= <value>           dotted identifiers compared segment-wise
26	//                                    numeric — '60821.10' is ten past '60821.3',
27	//                                    where floats and string order both lie
28	
29	export const LIVE_FIELD = 'Live-probe';
30	export const VERIFY_FIELD = 'Verify-probe';
31	export const RETRY_FIELD = 'Retry-every';
32	export const ORIGINAL_FIELD = 'Original-issue';
33	
34	const UNIT_MS = { minute: 60_000, hour: 3_600_000, day: 86_400_000, week: 7 * 86_400_000 };
35	
36	// `<count> <unit>` and nothing else. Null for anything unreadable — absence is a
37	// problem the caller names, never a default cadence nobody chose.
38	export function parseRetryEvery(text) {
39	  const m = /^(\d+)\s*(minute|hour|day|week)s?$/i.exec(String(text ?? '').trim());
40	  return m ? Number(m[1]) * UNIT_MS[m[2].toLowerCase()] : null;
41	}
42	
43	// One assertion, or null for a line that reads as none. Values after json ops are
44	// JSON literals; one that does not parse is taken as a bare string, so
45	// `== fleet` and `== "fleet"` assert the same thing.
46	export function parseAssertion(text) {
47	  const s = String(text ?? '').trim();
48	  let m;
49	  if ((m = /^status\s+(\d{3})$/.exec(s))) return { op: 'status', status: Number(m[1]) };
50	  if ((m = /^(not\s+)?contains\s+(.+)$/.exec(s))) {
51	    return { op: 'contains', negate: !!m[1], text: m[2] };
52	  }
53	  if ((m = /^(not\s+)?matches\s+\/(.*)\/([a-z]*)$/.exec(s))) {
54	    try {
55	      // Compiled here so an unreadable pattern is a parse problem, not a run crash.
56	      void new RegExp(m[2], m[3]);
57	    } catch { return null; }
58	    return { op: 'matches', negate: !!m[1], source: m[2], flags: m[3] };
59	  }
60	  if ((m = /^json\s+(\S+)\s+exists$/.exec(s))) return { op: 'json-exists', path: m[1] };
61	  if ((m = /^json\s+(\S+)\s+(==|!=|>=)\s+(.+)$/.exec(s))) {
62	    const raw = m[3].trim();
63	    let value;
64	    try { value = JSON.parse(raw); } catch { value = raw; }
65	    const op = { '==': 'json-eq', '!=': 'json-ne', '>=': 'json-gte' }[m[2]];
66	    return { op, path: m[1], value };
67	  }
68	  return null;
69	}
70	
71	// Dotted identifiers compared segment-wise numeric, a missing segment counting
72	// zero. Kept string-typed end to end — '60820.10' and '60820.1' are different
73	// versions and the same float. A non-numeric segment falls back to string order
74	// for that segment.
75	export function compareDotted(a, b) {
76	  const as = String(a).split('.');
77	  const bs = String(b).split('.');
78	  for (let i = 0; i < Math.max(as.length, bs.length); i += 1) {
79	    const [x, y] = [as[i] ?? '0', bs[i] ?? '0'];
80	    const [nx, ny] = [Number(x), Number(y)];
81	    const cmp = Number.isNaN(nx) || Number.isNaN(ny)
82	      ? x.localeCompare(y)
83	      : nx - ny;
84	    if (cmp !== 0) return cmp < 0 ? -1 : 1;
85	  }
86	  return 0;
87	}
88	
89	const dig = (value, path) => path.split('.').reduce(
90	  (v, seg) => (v !== null && typeof v === 'object' ? v[seg] : undefined), value);
91	
92	const deepEq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
93	
94	// Judge one assertion against one response ({ status, body }). Returns
95	// { ok, observed } — the observation is what was actually read, which is the
96	// evidence half of every verdict this task reports.
97	export function evaluateAssertion(assertion, { status, body }) {
98	  if (assertion.op === 'status') {
99	    return { ok: status === assertion.status, observed: `HTTP ${status}` };
100	  }
101	  if (status < 200 || status >= 300) return { ok: false, observed: `HTTP ${status}` };
102	  if (assertion.op === 'contains') {
103	    const found = body.includes(assertion.text);
104	    return { ok: found !== assertion.negate, observed: found ? 'text present' : 'text absent' };
105	  }
106	  if (assertion.op === 'matches') {
107	    const found = new RegExp(assertion.source, assertion.flags).test(body);
108	    return { ok: found !== assertion.negate, observed: found ? 'pattern present' : 'pattern absent' };
109	  }
110	  // The json ops.
111	  let parsed;
112	  try { parsed = JSON.parse(body); } catch { return { ok: false, observed: 'body is not JSON' }; }
113	  const actual = dig(parsed, assertion.path);
114	  const observed = actual === undefined ? `${assertion.path} absent` : `read ${JSON.stringify(actual)}`;
115	  if (assertion.op === 'json-exists') return { ok: actual !== undefined, observed };
116	  if (actual === undefined) return { ok: assertion.op === 'json-ne', observed };
117	  if (assertion.op === 'json-eq') return { ok: deepEq(actual, assertion.value), observed };
118	  if (assertion.op === 'json-ne') return { ok: !deepEq(actual, assertion.value), observed };
119	  return { ok: compareDotted(actual, assertion.value) >= 0, observed };
120	}
121	
122	// Parse a verification issue's human text into the spec the worker runs. Every
123	// gap or unreadable line is a PROBLEM by name — the item then parks with the
124	// list rather than half-running a spec that silently dropped a probe.
125	export function parseVerificationSpec(text) {
126	  const problems = [];
127	  const live = [];
128	  const verify = [];
129	  const probeRe = new RegExp(`^(${LIVE_FIELD}|${VERIFY_FIELD}):[ \\t]*(.*)$`, 'gm');
130	  for (const m of String(text ?? '').matchAll(probeRe)) {
131	    const [field, rest] = [m[1], m[2].trim()];
132	    const parts = /^(\S+)\s*::\s*(.+)$/.exec(rest);
133	    const url = parts?.[1] ?? null;
134	    const assertion = parts ? parseAssertion(parts[2]) : null;
135	    if (!url || !/^https?:\/\//.test(url) || !assertion) {
136	      problems.push(`unreadable ${field} line: \`${rest}\` — expected \`https://… :: <assertion>\``);
137	      continue;
138	    }
139	    (field === LIVE_FIELD ? live : verify).push({ url, assertion, raw: parts[2].trim() });
140	  }
141	  const originalIssue = (() => {
142	    const m = new RegExp(`^${ORIGINAL_FIELD}:[ \\t]*#?(\\d+)`, 'm').exec(String(text ?? ''));
143	    return m ? Number(m[1]) : null;
144	  })();
145	  const retryRaw = new RegExp(`^${RETRY_FIELD}:[ \\t]*(.+)$`, 'm').exec(String(text ?? ''))?.[1]?.trim() ?? null;
146	  const retryEveryMs = parseRetryEvery(retryRaw);
147	
148	  if (!live.length) problems.push(`no ${LIVE_FIELD}: line — without a liveness gate, "not deployed yet" and "deployed and broken" are indistinguishable`);
149	  if (!verify.length) problems.push(`no ${VERIFY_FIELD}: line — nothing would be verified`);
150	  if (!originalIssue) problems.push(`no ${ORIGINAL_FIELD}: line — a failing verification would have nowhere to land`);
151	  if (!retryEveryMs) problems.push(`no readable ${RETRY_FIELD}: line — expected \`<count> <minutes|hours|days|weeks>\``);
152	  return { originalIssue, retryEveryMs, retryRaw, live, verify, problems };
153	}
154	
155	// Run one probe class. Each URL is fetched ONCE however many probes read it;
156	// `fetchUrl(url)` resolves to { status, body } or throws, and a throw fails the
157	// probe with the error as its observation rather than the run.
158	export async function runProbes(probes, fetchUrl) {
159	  const responses = new Map();
160	  const results = [];
161	  for (const probe of probes) {
162	    if (!responses.has(probe.url)) {
163	      responses.set(probe.url, await fetchUrl(probe.url).catch((e) => ({ error: e.message })));
164	    }
165	    const response = responses.get(probe.url);
166	    results.push(response.error
167	      ? { probe, ok: false, observed: `fetch failed: ${response.error}` }
168	      : { probe, ...evaluateAssertion(probe.assertion, response) });
169	  }
170	  return results;
171	}
172	
173	export const renderResult = ({ probe, ok, observed }) =>
174	  `${ok ? 'PASS' : 'FAIL'} — ${probe.url} :: ${probe.raw} — ${observed}`;
175

