580	// The machine's half to read fields out of: the block where there is one, the whole
581	// body otherwise.
582	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
583	
584	// Replace the block, or append one to a body that has none. The human's text is
585	// never rewritten — an append lands after it, separated by a blank line.
586	export function withMachineBlock(body, block) {
587	  const text = String(body ?? '');
588	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
589	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
590	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
591	}
592	
593	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
594	// item body — a Context section, code-work's delivered list, a stamped
595	// `Not-before` — goes through here, so it edits the block on a marked issue and the
596	// whole body on a `[claudinite-work]` item, with one call site either way.
597	export function editItemBody(body, edit) {
598	  const block = machineBlockOf(body);
599	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
600	}
601	
602	// The human's half of a body — everything the machine block is not. A marked
603	// issue's PARAMETERS are read from here and never from the block: re-asking clears
604	// the status and leaves the previous run's block standing, and a parser that read
605	// the whole body would find that stale copy beside the person's own field.
606	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
607	
608	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
609	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
610	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
611	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
612	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
613	const ENDS_WHEN_RE = /^Ends-when:[ \t]*#(\d+)[ \t]+(\S+)[ \t]*$/m;
614	const TARGET_BRANCH_RE = /^Target-branch:[ \t]*(\S+)[ \t]*$/m;
615	const TARGET_PR_RE = /^Target-pr:[ \t]*#?(\d+)[ \t]*$/m;
616	const SUPERSEDES_RE = /^Supersedes:[ \t]*(.*)$/m;
617	const WOKEN_RE = /^Woken:[ \t]*(\S+)[ \t]*$/m;
618	
619	// Build a work item body. The first line is the task path — the only thing an
620	// executor reads to locate the worker, validated in code before anything trusts
621	// it. Everything behavior-defining (model, ceiling, worker content, code-work
622	// command) is read from the tracked task files at HEAD, never from here.
623	export function workItemBody({
624	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
625	  request = null, model = null, merge = null, woken = null,
626	}) {
627	  const lines = [taskPath, ''];
628	  const fields = [];
629	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
630	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
631	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
632	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
633	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
634	  if (woken) fields.push(`${WOKEN_FIELD}: ${woken}`);
635	  if (fields.length) lines.push(...fields, '');
636	  lines.push('Execute the Claudinite task above.');
637	  if (context.length) {
638	    lines.push(
639	      'The Context section below is binding scope — do not re-decide it.',
640	      '',
641	      '### Context',
642	      ...context.map((c) => `- ${c}`),
643	    );
644	  }
645	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
646	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
647	  return lines.join('\n') + '\n';
648	}
649	
650	// The `Blocked-by` numbers a body names, from a work item's body or from an
651	// ORDINARY issue's — a request marked for implementation states what it waits on in
652	// the same field spelling, and adoption carries it onto the item it births (PRINCIPLES.md).
653	export function parseBlockedBy(body) {
654	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
655	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
656	}
657	
658	// Parse an item body back into the facts the scheduler run and the executor read. A body
659	// with no first line, or whose fields are absent, yields nulls — absence is
660	// meaningful everywhere here and is never filled in with a default.
661	export function parseWorkItemBody(body) {
662	  const text = itemFieldText(body);
663	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
664	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
665	  const blockedBy = parseBlockedBy(text);
666	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
667	  // An unrecognised family reads as absent rather than as itself: the item's model
668	  // is behaviour-defining, so the only values that leave this parser are ones the
669	  // engine can actually dispatch at (PRINCIPLES.md).
670	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
671	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
672	  // Same fencing as the model: an authorization that does not read as a policy
673	  // expression reads as absent, and absent is the safe end of this field — a run
674	  // that cannot read its permission opens a pull request and waits.
675	  const merge = policyFieldValue(MERGE_RE.exec(text)?.[1] ?? null);
676	  // Same fencing again, and here it is what keeps the janitor honest: a condition
677	  // it cannot evaluate must read as "no end condition", never as one that is met.
678	  const ends = ENDS_WHEN_RE.exec(text);
679	  const endsWhen = ends && ends[2] === ENDS_WHEN_CLOSED ? Number(ends[1]) : null;
680	  const targetBranch = TARGET_BRANCH_RE.exec(text)?.[1] ?? null;
